GRANT SELECT,UPDATE ON "OutboxEvent" TO resolve_ai,resolve_ai_test;
CREATE POLICY ai_delivery ON "OutboxEvent" TO resolve_ai,resolve_ai_test USING("eventType"='ai.analyze' AND "merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "AIWorkerTenant" w WHERE w."merchantId"="OutboxEvent"."merchantId" AND w."roleName"=current_user)) WITH CHECK("eventType"='ai.analyze' AND "merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "AIWorkerTenant" w WHERE w."merchantId"="OutboxEvent"."merchantId" AND w."roleName"=current_user));
CREATE POLICY ai_prepare_delivery ON "OutboxEvent" TO resolve_evidence,resolve_evidence_test USING("eventType"='ai.prepare' AND "merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="OutboxEvent"."merchantId" AND w."roleName"=current_user)) WITH CHECK("eventType"='ai.prepare' AND "merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="OutboxEvent"."merchantId" AND w."roleName"=current_user));